function whatsappUrl(phone: string) {
  const digits = phone.replace(/\D/g, "");
  const international = digits.startsWith("20") ? digits : digits.replace(/^0/, "20");
  return `https://wa.me/${international}`;
}

function packagingKindForType(type: string | null | undefined): PackagingKind {
  return type === "BAG" ? "sack" : type === "JERRY_CAN" ? "jerrycan" : type === "CARTON" ? "carton" : "default";
}

function PackagingImages({ kinds, compact = false }: { kinds: PackagingKind[]; compact?: boolean }) {
  const uniqueKinds: PackagingKind[] = Array.from(new Set<PackagingKind>(kinds.length ? kinds : ["default"]));
  return <div className={`flex items-center ${compact ? "-space-x-2" : "gap-2"}`} dir="ltr">{uniqueKinds.map(kind => { const image = packagingImages[kind]; return <div key={kind} title={image.label} className={`${compact ? "h-10 w-10" : "h-14 w-14"} overflow-hidden rounded-xl border border-cyan-300/20 bg-[#071b31] p-1 shadow-[0_0_18px_rgba(34,211,238,.12)]`}><img src={image.src} alt={image.label} loading="lazy" className="h-full w-full object-contain" /></div>; })}</div>;
}

