const PREPARATION_QUEUE_KEY = "maddix:preparation-sync-queue";
type QueuedPreparation = { orderId: number; itemId: number; status: "PREPARING" | "PREPARED"; operationId: string; updatedAt: number };
function readPreparationQueue(): QueuedPreparation[] {
  if (typeof window === "undefined") return [];
  try { const parsed = JSON.parse(window.localStorage.getItem(PREPARATION_QUEUE_KEY) || "[]"); return Array.isArray(parsed) ? parsed : []; } catch { return []; }
}
function writePreparationQueue(queue: QueuedPreparation[]) {
  if (typeof window === "undefined") return;
  try { window.localStorage.setItem(PREPARATION_QUEUE_KEY, JSON.stringify(queue)); } catch { /* Storage may be unavailable; server state remains authoritative. */ }
}
function queuePreparation(item: QueuedPreparation) {
  const queue = readPreparationQueue().filter(entry => !(entry.orderId === item.orderId && entry.itemId === item.itemId));
  queue.push(item); writePreparationQueue(queue);
}
function removeQueuedPreparation(orderId: number, itemId: number) {
  writePreparationQueue(readPreparationQueue().filter(entry => !(entry.orderId === orderId && entry.itemId === itemId)));
}

